   448    UINT          length;         /* Byte length of this subtable. */
   449    UINT          language;       /* Ignore. */
   450    UINT          startCharCode;  /* First character code covered. */
   451    ArrayOf<GlyphID, UINT>
   452                  glyphIdArray;   /* Array of glyph index values for character
